            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const changeEvents = rows.filter(r => r.measurement === 'medication_dosage_history')
                .map(r => ({ date: r.time.slice(0, 10), medication: (r.tags && r.tags.medication_name) || 'unknown' }));
            const weight = toDaySeries(rows.filter(r => r.field === 'weight_lb'));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const mood = toDaySeries(rows.filter(r => r.field === 'mood_rating'));
            const incidentDays = {};
            rows.filter(r => r.measurement === 'incidents').forEach(r => { incidentDays[r.time.slice(0, 10)] = (incidentDays[r.time.slice(0, 10)] || 0) + 1; });
            function windowAvg(series, evT, dir) {
                const pts = series.filter(p => { const d = new Date(p.date).getTime() - evT; return dir < 0 ? (d >= -14 * 86400000 && d < 0) : (d >= 0 && d <= 14 * 86400000); });
                return mean(pts.map(p => p.value));
            }
            function windowIncidentCount(evT, dir) {
                let c = 0;
                Object.entries(incidentDays).forEach(([d, n]) => { const diff = new Date(d).getTime() - evT; if (dir < 0 ? (diff >= -14 * 86400000 && diff < 0) : (diff >= 0 && diff <= 14 * 86400000)) c += n; });
                return c;
            }
            const changes = changeEvents.map(ev => {
                const evT = new Date(ev.date).getTime();
                return {
                    date: ev.date, medication: ev.medication,
                    weight_before: windowAvg(weight, evT, -1), weight_after: windowAvg(weight, evT, 1),
                    hrv_before: windowAvg(hrv, evT, -1), hrv_after: windowAvg(hrv, evT, 1),
                    mood_before: windowAvg(mood, evT, -1), mood_after: windowAvg(mood, evT, 1),
                    incidents_before: windowIncidentCount(evT, -1), incidents_after: windowIncidentCount(evT, 1),
                };
            });
            return { label: 'Medication dosage-change correlation (14-day before/after windows)', changes };
        },
