            };
            const keys = Object.keys(series);
            const matrix = [];
            keys.forEach(a => keys.forEach(b2 => {
                if (a >= b2) return; // upper triangle only, avoid duplicate/self pairs
                const { xs, ys } = alignByDay(series[a], series[b2]);
                matrix.push({ a, b: b2, correlation: pearsonCorrelation(xs, ys), paired_days: xs.length });
            }));
