    unreported_anxiety_detection: {
        n: 18,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents" or (r._measurement == "oura_sleep" and (r._field == "average_hrv" or r._field == "lowest_heart_rate" or r._field == "efficiency") and (r.type == "long_sleep" or r.type == "sleep")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = new Set(rows.filter(r => r.measurement === 'incidents').map(r => r.time.slice(0, 10)));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const rhr = toDaySeries(rows.filter(r => r.field === 'lowest_heart_rate'));
            const eff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            function baseline(series, onIncidentDays) {
                const vals = series.filter(p => onIncidentDays === incidentDays.has(p.date)).map(p => p.value);
                return { avg: mean(vals), n: vals.length };
            }
            const hrvIncident = baseline(hrv, true), hrvNormal = baseline(hrv, false);
            const rhrIncident = baseline(rhr, true), rhrNormal = baseline(rhr, false);
            const effIncident = baseline(eff, true), effNormal = baseline(eff, false);
            // Flag a NON-incident day as a possible unreported-anxiety day
            // if HRV is below the incident-day average AND resting HR is
            // above the incident-day average AND sleep efficiency is
            // below the incident-day average — all three, deliberately
            // conservative (fewer false positives) since this is a
            // pattern-match against a small baseline, not a diagnosis.
            const flagged = [];
            hrv.forEach(p => {
                if (incidentDays.has(p.date)) return;
                const r = rhr.find(x => x.date === p.date);
                const e = eff.find(x => x.date === p.date);
                if (!r || !e || hrvIncident.avg === null || rhrIncident.avg === null || effIncident.avg === null) return;
                if (p.value <= hrvIncident.avg && r.value >= rhrIncident.avg && e.value <= effIncident.avg) {
                    flagged.push({ date: p.date, hrv: p.value, resting_hr: r.value, sleep_efficiency: e.value });
                }
            });
            return {
                label: 'Unreported-anxiety detection',
                incident_day_baseline: { hrv: hrvIncident, resting_hr: rhrIncident, sleep_efficiency: effIncident },
                normal_day_baseline: { hrv: hrvNormal, resting_hr: rhrNormal, sleep_efficiency: effNormal },
                flagged_days: flagged,
                note: 'Pattern-match against known incident days, not a diagnosis — needs real incident history to mean anything, per PLAN.md section 11 analysis #18. Likely to want more data before trusting.',
            };
        },
    },
    bedtime_wake_time_trend: {
        n: 19,
        flux: (b, s, e) => fluxFieldTrend(b, s, e, 'oura_sleep', 'time_in_bed', 'r.type == "long_sleep" or r.type == "sleep"'),
        shape: rows => {
            // bedtime_start IS the row's own _time (that's what the sleep
            // record is timestamped at, see oura_sync_flow.json's
            // sleepRecordToLine). Wake time = bedtime + time_in_bed
            // seconds — PLAN.md #19 flagged needing to confirm this at
            // build time; time_in_bed is the best available proxy for
            // total elapsed span without a separate bedtime_end field.
            const points = rows.filter(r => r.field === 'time_in_bed').map(r => {
                const bedtime = new Date(r.time);
                const wake = new Date(bedtime.getTime() + Number(r.value) * 1000);
                return { date: r.time.slice(0, 10), bedtime_hour: bedtime.getHours() + bedtime.getMinutes() / 60, wake_hour: wake.getHours() + wake.getMinutes() / 60 };
            });
            return {
                label: 'Bedtime / wake-time trend',
                series: points,
                avg_bedtime_hour: mean(points.map(p => p.bedtime_hour)),
                avg_wake_hour: mean(points.map(p => p.wake_hour)),
                note: 'wake_hour derived from bedtime + time_in_bed, not a direct Oura bedtime_end field — confirm against real data on first run (PLAN.md §11 #19).',
            };
        },
    },
    sleep_stage_hypnogram: {
        n: 20,
        // Only the MOST RECENT night in the window is used (see shape()
        // below) — a hypnogram is a per-night chart, not a multi-night
        // aggregate. Deliberately still queries the SAME window as every
        // other analysis this run rather than a special narrower range —
        // one uniform period-window per run keeps the engine's one code
        // path simple; fetching more decomposed points than strictly
        // needed and discarding all but the latest night is wasteful but
        // cheap at this project's actual data volume.
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "oura_sleep_stage")\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            // oura_sleep_stage only ever has one field ('value', see
            // decomposeSleepPhase() in oura_sync_flow.json) so this
            // filter is belt-and-suspenders rather than load-bearing —
            // consistent with the explicit field filters elsewhere in
            // this file, not strictly required by this measurement's own
            // shape the way it is for e.g. sleep_duration_trend.
            const stageRows = rows.filter(r => r.field === 'value');
            if (!stageRows.length) return { label: 'Sleep-stage timeline (hypnogram)', buckets: [], note: 'No decomposed oura_sleep_stage points in range yet.' };
            // Most recent sleep_id present.
            const bySleepId = {};
            stageRows.forEach(r => { (bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] = bySleepId[(r.tags && r.tags.sleep_id) || 'unknown'] || []).push(r); });
            const latestId = Object.keys(bySleepId).sort((a, b) => {
                const ta = bySleepId[a][0].time, tb = bySleepId[b][0].time; return ta < tb ? -1 : 1;
            }).pop();
            const nightRows = bySleepId[latestId].sort((a, b) => a.time < b.time ? -1 : 1);
            const buckets = nightRows.map(r => ({ time: r.time, stage: (r.tags && r.tags.stage) || 'unknown' }));
            return {
                label: 'Sleep-stage timeline (hypnogram)',
                sleep_id: latestId,
                bounds: { start: buckets.length ? buckets[0].time : null, end: buckets.length ? buckets[buckets.length - 1].time : null },
                buckets,
                note: 'SLEEP_STAGE_MAP (1=deep/2=light/3=rem/4=awake) is assumed, not confirmed against real data — see the note in oura_sync_flow.json, PLAN.md section 11 analysis #20.',
            };
        },
    },
};

// ---- driver: parse the CSV this analysis's query returned, then shape it ----
if (msg.analysis_skip) return msg; // unknown-key case from the previous node, nothing to do
const def = ANALYSES[msg.analysis_key];
let result;
try {
    const rows = parseFluxCsvToRows(msg.payload || '');
    result = def.shape(rows);
} catch (e) {
    // A shaping bug in ONE analysis (bad Flux response shape, a real edge case the shape function
    // doesn't handle) shouldn't take down the whole run — record it as this analysis's own result
    // rather than throwing, which would abort the split/join for every other analysis too.
    node.warn('Shape function failed for ' + msg.analysis_key + ': ' + e.message);
    result = { error: 'shape_failed', message: e.message };
}
msg.analysis_result = result;
const secrets = flow.get('ae_secrets');
msg.payload = JSON.stringify({
    analysis_key: msg.analysis_key,
    period_type: msg.period_type,
    period_start: msg.period_start_date,
    period_end: msg.period_end_date,
    analysis_version: 1,
    result: result,
    computed_at: new Date().toISOString(),
});
msg.url = secrets.godaddy_base_url + '/api/analysis_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
return msg;

// n_ae_join's count is a fixed 20 (ANALYSIS_KEYS.length at build time) — msg.payload here is just
// an array of whatever each push's response was, only its length matters for a basic sanity count.
const results = Array.isArray(msg.payload) ? msg.payload : [];
msg.analyses_completed = results.length;
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(flow.get('ae_job_started_at') || Date.now()).getTime();
msg.secrets = flow.get('ae_secrets');
msg.job_started_at = flow.get('ae_job_started_at');
msg.influx_finish_point = 'sync_job_runs,job_name=analysis_engine,period_type=' + flow.get('ae_period_type') + ',status=success analyses_completed=' + (msg.analyses_completed || 0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'analysis_engine', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1 };
return msg;

const nowNs = Date.now() * 1000000;
const detail = ((msg.error && msg.error.message) || 'unknown error').toString();
const source = (msg.error && msg.error.source && msg.error.source.name) || 'unknown node';
const safeDetail = (source + ': ' + detail).replace(/([ ,="])/g, '\\$1');
msg.secrets = flow.get('ae_secrets');
msg.job_started_at = flow.get('ae_job_started_at');
msg.influx_finish_point = 'sync_job_runs,job_name=analysis_engine,period_type=' + (flow.get('ae_period_type') || 'unknown') + ',status=failed,failure_code=flow_error detail="' + safeDetail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'analysis_engine', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: (source + ': ' + detail).slice(0, 250) };
node.warn('Analysis Engine failed: ' + source + ': ' + detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

// Ensures the shared status table exists before every write — cheap
// no-op if it already does. Same idempotent CREATE TABLE IF NOT EXISTS
// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
